import helmet from 'helmet';  // npm install helmet

// Helmet sets most security headers automatically
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],  // adjust for your CDN
      styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
      fontSrc: ["'self'", "https://fonts.gstatic.com"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'", "https://api.myapp.com"],
    },
  },
  // Prevents clickjacking
  frameguard: { action: 'deny' },
  // Forces HTTPS for 1 year
  hsts: { maxAge: 31536000, includeSubDomains: true },
}));

// Verify headers at: https://securityheaders.com
// Also: https://observatory.mozilla.org/analyze/myapp.com
